solution.solution.js:
class ValidationError extends Error {
  constructor(field, message, options) {
    super(message, options);
    this.name = "ValidationError";
    this.field = field;
  }
}

function parseSignup(json) {
  if (typeof json !== "string") throw new TypeError("json must be a string");
  let data;
  try {
    data = JSON.parse(json);
  } catch (err) {
    throw new ValidationError("json", "not valid JSON", { cause: err });
  }
  if (data === null || typeof data !== "object" || Array.isArray(data)) {
    throw new ValidationError("json", "expected an object");
  }
  const { name, age, email } = data;
  if (typeof name !== "string" || name.trim().length < 2) throw new ValidationError("name", "name is too short");
  if (!Number.isInteger(age) || age < 13 || age > 120) throw new ValidationError("age", "age must be 13 to 120");
  const parts = typeof email === "string" ? email.split("@") : [];
  if (parts.length !== 2 || !parts[0] || !parts[1]) throw new ValidationError("email", "email is not valid");
  return { name: name.trim(), age, email: email.toLowerCase() };
}

function trySignup(json) {
  try {
    return { ok: true, user: parseSignup(json) };
  } catch (err) {
    if (err instanceof ValidationError) return { ok: false, field: err.field, message: err.message };
    throw err;
  }
}

unitTests:
test("a valid signup", () => {
  checkEq(parseSignup('{"name": "  Ada ", "age": 36, "email": "Ada@Example.com", "admin": true}'),
    { name: "Ada", age: 36, email: "ada@example.com" });
});

test("the error class", () => {
  const e = new ValidationError("age", "too old");
  check(e instanceof Error, "should extend Error");
  checkEq([e.name, e.field, e.message], ["ValidationError", "age", "too old"]);
});

test("each rule in order", () => {
  const r = json => trySignup(json);
  checkEq(r("{oops"), { ok: false, field: "json", message: "not valid JSON" });
  checkEq(r("[1, 2]"), { ok: false, field: "json", message: "expected an object" });
  checkEq(r("null"), { ok: false, field: "json", message: "expected an object" });
  checkEq(r('{"name": " A ", "age": 5}'), { ok: false, field: "name", message: "name is too short" });
  checkEq(r('{"name": "Bo", "age": 12, "email": "x"}'), { ok: false, field: "age", message: "age must be 13 to 120" });
  checkEq(r('{"name": "Bo", "age": 20.5}'), { ok: false, field: "age", message: "age must be 13 to 120" });
  checkEq(r('{"name": "Bo", "age": 20, "email": "a@b@c"}'), { ok: false, field: "email", message: "email is not valid" });
  checkEq(r('{"name": "Bo", "age": 20, "email": "@b"}'), { ok: false, field: "email", message: "email is not valid" });
  checkEq(r('{"name": "Bo", "age": 20, "email": "a@b"}').ok, true);
});

test("the JSON error keeps its cause", () => {
  try {
    parseSignup("{bad");
    check(false, "should have thrown");
  } catch (e) {
    check(e instanceof ValidationError, "should be a ValidationError");
    check(e.cause instanceof SyntaxError, "cause should be the SyntaxError");
  }
});

test("other errors are rethrown", () => {
  checkThrows(() => trySignup(undefined), TypeError);
});

